1	//! Modal for accepting an invitation by pasting either the full URL
2	//! or the bare invitation code.
3	//!
4	//! On web River reads invitations from `window.location().search()` —
5	//! the URL bar IS the invitation surface. On Android there's no URL
6	//! bar, no DOM `window` (`platform::window()` returns `None`), and
7	//! the click interceptor is a no-op. Without this modal, an Android
8	//! user has no way to act on an invitation URL sent to them out-of-
9	//! band (Signal, email, etc.) other than installing River on a desktop
10	//! browser first. Section 8.2 of the openspec change calls this out.
11	//!
12	//! The modal accepts both:
13	//!   - A full URL: `http://.../?invitation=N4so...` (anything containing
14	//!     `?invitation=` is treated as a URL; everything after that prefix
15	//!     up to the first `#` or `&` is the code)
16	//!   - The bare base58 code: `N4so...`
17	//!
18	//! On success it calls [`crate::components::room_list::receive_invitation_modal::present_invitation`],
19	//! which is the same path the in-app DM-thread "Accept" button takes —
20	//! deferred signal write into `PRESENT_INVITATION_REQUEST`, picked up by
21	//! `App`'s bridge effect, opens `ReceiveInvitationModal`.
22	
23	use crate::components::members::Invitation;
24	use crate::components::room_list::receive_invitation_modal::present_invitation;
25	use dioxus::prelude::*;
26	
27	/// Extract the invitation code from arbitrary user-pasted input.
28	///
29	/// Pure helper so it can be unit-tested without a Dioxus runtime.
30	pub(super) fn extract_code(input: &str) -> &str {
31	    let trimmed = input.trim();
32	    match trimmed.find("?invitation=") {
33	        Some(idx) => {
34	            let after = &trimmed[idx + "?invitation=".len()..];
35	            // Stop at fragment / next query param boundary
36	            match after.find(['#', '&']) {
37	                Some(end) => &after[..end],
38	                None => after,
39	            }
40	        }
41	        None => trimmed,
42	    }
43	}
44	
45	#[component]
46	pub fn PasteInvitationModal(is_active: Signal<bool>) -> Element {
47	    let mut input = use_signal(String::new);
48	    let mut error_msg = use_signal(|| None::<String>);
49	
50	    if !*is_active.read() {
51	        return rsx! {};
52	    }
53	
54	    let close = move |_| {
55	        is_active.set(false);
56	        input.set(String::new());
57	        error_msg.set(None);
58	    };
59	
60	    let handle_join = move |_| {
61	        let raw = input.read().clone();
62	        let code = extract_code(&raw);
63	        if code.is_empty() {
64	            error_msg.set(Some("Paste an invitation URL or code first.".to_string()));
65	            return;
66	        }
67	        match Invitation::from_encoded_string(code) {
68	            Ok(inv) => {
69	                // present_invitation defers the signal write via
70	                // crate::util::defer (setTimeout on wasm, synchronous on
71	                // native — safe from this onclick handler context).
72	                //
73	                // KNOWN ANDROID CRASH (TODO): on Android the subsequent
74	                // render of ReceiveInvitationModal triggers a panic
75	                // inside dioxus / wry's
76	                // `Java_dev_dioxus_main_RustWebViewClient_handleRequest`
77	                // JNI callback (panic_cannot_unwind at the FFI
78	                // boundary → SIGABRT). The decode + handoff path here
79	                // works fine; the crash happens downstream when the
80	                // newly-rendered modal causes the WebView to fetch a
81	                // resource the custom-protocol handler doesn't expect.
82	                // Reproduced on Pixel 10 Pro XL with the full public-
83	                // chat invitation pasted via the system clipboard.
84	                // Investigation: the originating panic message wasn't
85	                // captured in logcat by the time the device dropped
86	                // off USB; will need to dig into dioxus-desktop /
87	                // wry's asset handler under
88	                // `target_os = "android"` next session.
89	                present_invitation(inv);
90	                // Close immediately; the global ReceiveInvitationModal
91	                // will open as soon as the bridge effect in App sees
92	                // PRESENT_INVITATION_REQUEST update.
93	                is_active.set(false);
94	                input.set(String::new());
95	                error_msg.set(None);
96	            }
97	            Err(e) => {
98	                error_msg.set(Some(format!(
99	                    "Couldn't decode invitation: {e}. Make sure you pasted the full URL or the code after '?invitation='."
100	                )));
101	            }
102	        }
103	    };
104	
