2	mod imp {
3	    use crate::components::app::freenet_api::constants::*;
4	    use crate::components::app::freenet_api::error::SynchronizerError;
5	    use crate::components::app::freenet_api::freenet_synchronizer;
6	    use crate::components::app::freenet_api::freenet_synchronizer::SynchronizerStatus;
7	    use crate::components::app::{AUTH_TOKEN, SYNC_STATUS, WEB_API};
8	    use crate::util::sleep;
9	    use dioxus::logger::tracing::{error, info, warn};
10	    use dioxus::prelude::ReadableExt;
11	    use freenet_stdlib::client_api::{ClientError, HostResponse, WebApi};
12	    use futures::channel::mpsc::UnboundedSender;
13	    use std::sync::atomic::{AtomicBool, Ordering};
14	    use std::time::Duration;
15	    use wasm_bindgen_futures::spawn_local;
16	
17	    /// Error prefix sent by freenet-core when auth token is invalid/stale.
18	    /// This typically happens after a node restart when the in-memory token map is cleared.
19	    const AUTH_TOKEN_INVALID_ERROR: &str = "AUTH_TOKEN_INVALID";
20	
21	    /// Guard to prevent multiple page reload tasks from being spawned.
22	    /// Once a reload is scheduled, subsequent AUTH_TOKEN_INVALID errors are ignored.
23	    static RELOAD_SCHEDULED: AtomicBool = AtomicBool::new(false);
24	
25	    /// Manages the connection to the Freenet node
26	    pub struct ConnectionManager {
27	        connected: bool,
28	    }
29	
30	    impl ConnectionManager {
31	        pub fn new() -> Self {
32	            info!("Creating new ConnectionManager");
33	            Self { connected: false }
34	        }
35	
36	        /// Check if the connection is established and ready
37	        pub fn is_connected(&self) -> bool {
38	            *SYNC_STATUS.read() == SynchronizerStatus::Connected
39	        }
40	
41	        /// Initializes the connection to the Freenet node
42	        pub async fn initialize_connection(
43	            &mut self,
44	            message_tx: UnboundedSender<freenet_synchronizer::SynchronizerMessage>,
45	        ) -> Result<(), SynchronizerError> {
46	            // Get auth token to add as query parameter
47	            let auth_token = AUTH_TOKEN.read().clone();
48	            let base_url = get_websocket_url();
49	            let websocket_url = if let Some(token) = auth_token {
50	                if base_url.contains('?') {
51	                    format!("{}&authToken={}", base_url, token)
52	                } else {
53	                    format!("{}?authToken={}", base_url, token)
54	                }
55	            } else {
56	                base_url
57	            };
58	
59	            info!("Connecting to Freenet node at: {}", websocket_url);
60	            *SYNC_STATUS.write() = SynchronizerStatus::Connecting;
61	            self.connected = false;
62	
63	            info!("Connecting to WebSocket URL: {}", websocket_url);
64	            let websocket = web_sys::WebSocket::new(&websocket_url).map_err(|e| {
65	                let error_msg = format!("Failed to create WebSocket: {:?}", e);
66	                error!("{}", error_msg);
67	                SynchronizerError::WebSocketError(error_msg)
68	            })?;
69	
70	            // Create a simple oneshot channel for connection readiness
71	            let (ready_tx, ready_rx) = futures::channel::oneshot::channel();
72	            let message_tx_clone = message_tx.clone();
73	
74	            info!("Starting WebAPI with callbacks");
75	
76	            // Clone message_tx for the error handler to trigger reconnection
77	            let error_tx = message_tx.clone();
78	
79	            let web_api = WebApi::start(
80	                websocket.clone(),
81	                move |result: Result<HostResponse, ClientError>| {
82	                    // Check for AUTH_TOKEN_INVALID error - this means the node was restarted
83	                    // and we need to refresh the page to get a new valid token
84	                    if let Err(ref e) = result {
85	                        let error_str = e.to_string();
86	                        if error_str.contains(AUTH_TOKEN_INVALID_ERROR) {
87	                            // Guard against multiple reload tasks being spawned
88	                            if RELOAD_SCHEDULED.swap(true, Ordering::SeqCst) {
89	                                info!("Page reload already scheduled, ignoring duplicate AUTH_TOKEN_INVALID");
90	                                return;
91	                            }
92	                            warn!(
93	                                "Auth token is no longer valid (node may have restarted). \
94	                                 Scheduling page refresh to get a new token."
95	                            );
96	                            // Don't reload immediately - this would interrupt any pending
97	                            // async operations like delegate registration. Instead, schedule
98	                            // the reload with a small delay to allow current operations to
99	                            // complete or fail gracefully.
100	                            spawn_local(async move {
101	                                // Check localStorage to prevent reload loops: if we
102	                                // reloaded recently (within 10s) and still get
103	                                // AUTH_TOKEN_INVALID, the cache is likely serving stale
104	                                // HTML. Stop reloading and tell the user to refresh.
105	                                if let Some(window) = crate::platform::window() {
106	                                    if let Ok(Some(storage)) = window.local_storage() {
107	                                        let now = js_sys::Date::now();
108	                                        if let Ok(Some(last)) =
109	                                            storage.get_item("river_last_auth_reload")
110	                                        {
111	                                            if let Ok(ts) = last.parse::<f64>() {
112	                                                if now - ts < 10_000.0 {
113	                                                    warn!("Auth reload loop detected — stopping automatic reload");
114	                                                    *SYNC_STATUS.write() =
115	                                                        freenet_synchronizer::SynchronizerStatus::Error(
116	                                                            "Connection lost. Please refresh the page.".to_string(),
117	                                                        );
118	                                                    return;
119	                                                }
120	                                            }
121	                                        }
122	                                        let _ = storage
123	                                            .set_item("river_last_auth_reload", &now.to_string());
124	                                    }
125	                                }
126	
127	                                *SYNC_STATUS.write() =
128	                                    freenet_synchronizer::SynchronizerStatus::Error(
129	                                        "Authentication expired. Refreshing page...".to_string(),
130	                                    );
131	                                // Wait for pending delegate registration to complete.
132	                                // This is needed because set_up_chat_delegate() might be
133	                                // running concurrently, and we need its WebSocket messages
134	                                // to be sent before we trigger a page reload.
135	                                // 500ms should be enough for the messages to be queued and
136	                                // sent over the WebSocket.
137	                                sleep(Duration::from_millis(500)).await;
138	                                // Navigate with cache-busting param to ensure the browser
139	                                // fetches fresh HTML (with a new auth token) from the
140	                                // gateway instead of serving a cached copy.
141	                                if let Some(window) = crate::platform::window() {
142	                                    let path = window
143	                                        .location()
144	                                        .pathname()
145	                                        .unwrap_or_else(|_| "/".to_string());
146	                                    let bust = js_sys::Date::now() as u64;
147	                                    let url = format!("{}?_reload={}", path, bust);
148	                                    if let Err(e) = window.location().set_href(&url) {
149	                                        error!("Failed to navigate for auth reload: {:?}", e);
150	                                    }
151	                                }
152	                            });
153	                            return; // Don't process this error further
154	                        }
155	                    }
156	
157	                    let mapped_result: Result<
158	                        freenet_stdlib::client_api::HostResponse,
159	                        SynchronizerError,
160	                    > = result.map_err(|e| SynchronizerError::WebSocketError(e.to_string()));
161	                    let tx = message_tx_clone.clone();
162	                    spawn_local(async move {
163	                        if let Err(e) = tx.unbounded_send(
164	                            freenet_synchronizer::SynchronizerMessage::ApiResponse(mapped_result),
165	                        ) {
166	                            error!("Failed to send API response: {}", e);
167	                        }
168	                    });
169	                },
170	                {
171	                    move |error| {
172	                        let error_msg = format!("WebSocket error: {}", error);
173	                        error!("{}", error_msg);
174	
175	                        // Check if this is a connection closed error
176	                        let is_connection_closed = error_msg.contains("connection closed");
177	
178	                        let tx = error_tx.clone();
179	                        spawn_local(async move {
180	                            *SYNC_STATUS.write() =
181	                                freenet_synchronizer::SynchronizerStatus::Error(error_msg);
182	
183	                            // Trigger reconnection for connection closed errors
184	                            if is_connection_closed {
185	                                info!("Connection closed, triggering reconnection");
186	                                if let Err(e) = tx.unbounded_send(
187	                                    freenet_synchronizer::SynchronizerMessage::ConnectionLost,
188	                                ) {
189	                                    error!("Failed to send ConnectionLost message: {}", e);
190	                                }
191	                            }
192	                        });
193	                    }
194	                },
195	                {
196	                    move || {
197	                        info!("WebSocket connected successfully");
198	                        // Clear the reload-loop guard so a future node restart can
199	                        // trigger a fresh reload without being falsely detected as a loop.
200	                        if let Some(window) = crate::platform::window() {
201	                            if let Ok(Some(storage)) = window.local_storage() {
202	                                let _ = storage.remove_item("river_last_auth_reload");
203	                            }
204	                        }
205	                        spawn_local(async move {
206	                            *SYNC_STATUS.write() =
207	                                freenet_synchronizer::SynchronizerStatus::Connected;
208	                        });
209	                        let _ = ready_tx.send(());
210	                    }
211	                },
212	            );
213	
214	            info!(
215	                "Waiting for connection with timeout of {}ms",
216	                CONNECTION_TIMEOUT_MS
217	            );
218	
219	            let timeout_future = sleep(Duration::from_millis(CONNECTION_TIMEOUT_MS));
220	
221	            let result =
222	                futures::future::select(Box::pin(ready_rx), Box::pin(timeout_future)).await;
223	
224	            match result {
225	                futures::future::Either::Left((Ok(_), _)) => {
226	                    info!("WebSocket connection established successfully");
227	                    *WEB_API.write() = Some(web_api);
228	                    self.connected = true;
229	                    *SYNC_STATUS.write() = SynchronizerStatus::Connected;
230	                    Ok(())
231	                }
232	                _ => {
233	                    let error = SynchronizerError::WebSocketError(
234	                        "WebSocket connection failed or timed out".to_string(),
235	                    );
236	                    error!("{}", error);
237	                    *SYNC_STATUS.write() =
238	                        freenet_synchronizer::SynchronizerStatus::Error(error.to_string());
239	
240	                    let ready_state = websocket.ready_state();
241	                    if ready_state == web_sys::WebSocket::CONNECTING
242	                        || ready_state == web_sys::WebSocket::OPEN
243	                    {
244	                        info!("Closing WebSocket due to connection failure");
245	                        if let Err(e) = websocket.close() {
246	                            error!("Failed to close WebSocket: {:?}", e);
247	                        }
248	                    }
249	
250	                    Err(error)
251	                }
252	            }
253	        }
254	    }
255	}
