#[derive(Clone)]
pub struct RoomNotifContext {
    pub owner_vk: ed25519_dalek::VerifyingKey,
    pub self_member_id: river_core::room_state::member::MemberId,
    /// Decrypted display name (UI holds the secrets; the watcher does not
    /// decrypt in Phase 1). Empty if not yet known.
    pub room_name: String,
    /// Max message timestamp (ms since epoch) the UI has already
    /// processed for this room. The watcher only notifies for messages
    /// strictly newer than this, and advances it after notifying so a
    /// state re-sync doesn't re-notify. Monotonic (max-on-write).
    pub last_seen_ms: u64,
}

/// `None` until first populated; lazily initialised on first write so it
/// can be a plain `const`-constructible static (`HashMap::new` is not
/// const). Keyed by the room owner's `MemberId`.
static NOTIF_CONTEXTS: std::sync::Mutex<
    Option<std::collections::HashMap<river_core::room_state::member::MemberId, RoomNotifContext>>,
> = std::sync::Mutex::new(None);

/// Publish (or refresh) the notification context for a room. Called from
/// the UI wherever it has live `RoomData`. `last_seen_ms` only ever
/// advances (max-on-write) so a stale caller can't rewind it. A no-op in
/// practice off-Android (the UI only calls this under
/// `cfg(target_os = "android")`), but defined cross-target so the call
/// site type-checks everywhere.
pub fn update_notif_context(
    owner_vk: ed25519_dalek::VerifyingKey,
    self_member_id: river_core::room_state::member::MemberId,
    room_name: String,
    last_seen_ms: u64,
) {
    use river_core::room_state::member::MemberId;
    let key = MemberId::from(&owner_vk);
    if let Ok(mut guard) = NOTIF_CONTEXTS.lock() {
        let map = guard.get_or_insert_with(std::collections::HashMap::new);
        let entry = map.entry(key).or_insert_with(|| RoomNotifContext {
            owner_vk,
            self_member_id,
            room_name: room_name.clone(),
            last_seen_ms,
        });
        entry.owner_vk = owner_vk;
        entry.self_member_id = self_member_id;
        if !room_name.is_empty() {
            entry.room_name = room_name;
        }
        entry.last_seen_ms = entry.last_seen_ms.max(last_seen_ms);
    }
}

